 hip(name,x0,x1,z0,z1,y0,eave,ridge,wall=C.stone,roof=C.slate){this.part(name);const lo=[[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1]],hi=lo.map(([x,y,z])=>[x,eave,z]),inset=Math.min(x1-x0,z1-z0)*.32,a=[(x0+x1)/2,ridge,z0+inset],b=[(x0+x1)/2,ridge,z1-inset];for(let i=0;i<4;i++){const j=(i+1)%4;this.face([lo[i],lo[j],hi[j],hi[i]],[(lo[i][0]+lo[j][0])/2-(x0+x1)/2,0,(lo[i][2]+lo[j][2])/2-(z0+z1)/2],wall);}this.face(lo,[0,-1,0],wall);this.face([hi[0],hi[1],a],[0,1,-1],roof);this.face([hi[1],hi[2],b,a],[1,1,0],roof);this.face([hi[2],hi[3],b],[0,1,1],roof);this.face([hi[3],hi[0],a,b],[-1,1,0],roof);return this;}
