function engineFarm(){const b=new Architecture('horse-engine-threshing-farm');b.halfHip('half-hipped-threshing-barn',.12,.63,.12,.80,.50,.66,.82,.13,C.stone,C.slate);b.pyramid('octagonal-horse-engine-house',ring(.74,.34,.19,8),0,.36,.57,C.stone,C.roof);b.gable('opposing-wagon-porch',.27,.48,.77,.94,0,.41,.60,C.timber,C.slate);b.door(.375,.941,0,.17,.30,C.oak);rearDoor(b,.375,.119,0,.22,.33);b.sideWindows(.119,.20,.73,.17,.10,.18,3,true,2,1);polygonWindows(b,ring(.74,.34,.19,8),[0,1,2,3],.11,.075,.14);for(const [i,x]of [.11,.16,.21].entries())b.box('cultivation-furrow-'+i,x-.012,x+.012,.85,.96,0,.015,'#647b46');return b.finish();}
