function bankBarn(){const b=new Architecture('lakeland-bank-barn-ranch');b.gable('two-level-livestock-hay-barn',.13,.68,.12,.62,0,.65,.92,C.stone,C.slate);b.ramp('grounded-wagon-bank',.66,.94,.27,.97,.35,C.stoneDark);b.box('upper-wagon-landing',.65,.94,.12,.29,0,.35,C.stoneDark);b.profile('stock-lean-to',[[.04,0],[.16,0],[.16,.38],[.04,.24]],.21,.53,C.stone,C.slate);sideDoor(b,.681,.205,.35,.13,.25);b.door(.35,.621,0,.18,.26,C.oak);rearDoor(b,.40,.119,0,.15,.25);b.window(.40,.621,.42,.15,.15,2,1);b.window(.40,.119,.42,.15,.15,2,1,true);sideDoor(b,.039,.37,0,.11,.19,true);for(const x of [.2,.57])b.window(x,.621,.10,.075,.12,1,1);return b.finish();}
function piggery(){const b=new Architecture('corbelled-stone-piggery');b.gable('feed-preparation-room',.12,.88,.08,.32,0,.28,.45,C.stone,C.slate);for(const [i,x]of [.25,.50,.75].entries())b.pyramid('pointed-corbelled-sty-'+i,ring(x,.37,.16,8),0,.23,.58,C.stone,C.stoneDark);for(const [i,x]of [.08,.36,.64,.92].entries())b.box('stock-pen-side-'+i,x-.014,x+.014,.47,.88,0,.13,C.stone);for(const [i,x]of [.21,.50,.79].entries())b.box('stock-pen-ground-gate-'+i,x-.11,x+.11,.865,.89,0,.10,C.oak);rearDoor(b,.5,.079,0,.14,.22);b.window(.25,.079,.10,.12,.12,2,1,true);b.window(.75,.079,.10,.12,.12,2,1,true);for(const x of [.25,.50,.75]){const start=b.parts.length;const a=ring(x,.37,.16,8)[7],c=ring(x,.37,.16,8)[0],dx=c[0]-a[0],dz=c[1]-a[1],L=Math.hypot(dx,dz),nx=-dz/L,nz=dx/L;b.door(0,0,0,.075,.16,C.oak);b.transformBasis(start,(a[0]+c[0])/2+nx*.001,(a[1]+c[1])/2+nz*.001,nz,nx);}return b.finish();}
